      "toolPasswordRegenerate": "換一組",
      "toolPasswordAlternatives": "備選密碼",
      "toolPasswordCopyHint": "點選任一行即可複製",
      "toolPasswordEntropy": "{strength} · 約 {bits} 位元理論熵（{size} 個字元）",
      "toolPasswordStrength1": "弱",
      "toolPasswordStrength2": "中等",
      "toolPasswordStrength3": "較強",
